  `double_value` Float64 DEFAULT 0,
  `float_value` Float32 DEFAULT 0,
  `int64_value` Int64 DEFAULT 0,
  `uint64_value` UInt64 DEFAULT 0,
  `int32_value` Int32 DEFAULT 0,
  `fixed64_value` UInt64 DEFAULT 0,
  `fixed32_value` UInt32 DEFAULT 0,
  `bool_value` Bool DEFAULT false,
  `string_value` String DEFAULT '',
  `bytes_value` String DEFAULT '',
  `uint32_value` UInt32 DEFAULT 0,
  `sfixed32_value` Int32 DEFAULT 0,
  `sfixed64_value` Int64 DEFAULT 0,
  `sint32_value` Int32 DEFAULT 0,
  `sint64_value` Int64 DEFAULT 0,
  `state` Int32 DEFAULT 0,
  `optional_note` Nullable(String) DEFAULT NULL,
  `nested` Tuple(`present` Bool, `value` Tuple(`id` Int64, `label` Nullable(String))),
  `labels` Array(String) DEFAULT [],
  `children` Array(Tuple(`id` Int64, `label` Nullable(String))) DEFAULT [],
  `counters` Map(String, UInt64) DEFAULT map(),
  `__invariant_oneof_choice_case` Int32 DEFAULT 0 COMMENT 'Invariant oneof discriminator for choice: 0=unset, 22=choice_count, 23=choice_name',
  `choice_count` Tuple(`present` Bool, `value` Int32),
  `choice_name` Tuple(`present` Bool, `value` String),
  `created_at` Nullable(DateTime64(9, 'UTC')) DEFAULT NULL,
  `elapsed` Nullable(Int64) DEFAULT NULL,
  `wrapped_count` Nullable(Int32) DEFAULT NULL,
  `attributes` Nullable(String) DEFAULT NULL,
  `opaque` Nullable(String) DEFAULT NULL,
  `amount` Nullable(Decimal(18, 4)) DEFAULT NULL COMMENT 'Semantic amount.',
  `record_id` Nullable(UUID) DEFAULT NULL COMMENT 'Semantic record_id.',
  `digest` Nullable(FixedString(24)) DEFAULT NULL COMMENT 'Semantic digest.',
  `json_value` Nullable(String) DEFAULT NULL COMMENT 'Semantic json_value.',
  `json_list` Nullable(String) DEFAULT NULL COMMENT 'Semantic json_list.',
  CONSTRAINT `invariant.string_value.utf8` CHECK isValidUTF8(`string_value`),
  CONSTRAINT `invariant.optional_note.utf8` CHECK isNull(`optional_note`) OR (isValidUTF8(assumeNotNull(`optional_note`))),
  CONSTRAINT `invariant.nested.label.utf8` CHECK NOT tupleElement(`nested`, 'present') OR (isNull(tupleElement(tupleElement(`nested`, 'value'), 'label')) OR (isValidUTF8(assumeNotNull(tupleElement(tupleElement(`nested`, 'value'), 'label'))))),
  CONSTRAINT `invariant.labels[].utf8` CHECK arrayAll(element -> (isValidUTF8(element)), `labels`),
  CONSTRAINT `invariant.children[].label.utf8` CHECK arrayAll(element -> (isNull(tupleElement(element, 'label')) OR (isValidUTF8(assumeNotNull(tupleElement(element, 'label'))))), `children`),
  CONSTRAINT `invariant.counters.map_keys` CHECK length(mapKeys(`counters`)) = length(arrayDistinct(mapKeys(`counters`))),
  CONSTRAINT `invariant.counters.key.utf8` CHECK arrayAll(key -> (isValidUTF8(key)), mapKeys(`counters`)),
  CONSTRAINT `invariant.choice.oneof_case` CHECK `__invariant_oneof_choice_case` IN (0, 22, 23),
  CONSTRAINT `invariant.choice_count.oneof_presence` CHECK (`__invariant_oneof_choice_case` = 22) = tupleElement(`choice_count`, 'present'),
  CONSTRAINT `invariant.choice_name.oneof_presence` CHECK (`__invariant_oneof_choice_case` = 23) = tupleElement(`choice_name`, 'present'),
  CONSTRAINT `invariant.choice_name.utf8` CHECK NOT tupleElement(`choice_name`, 'present') OR (isValidUTF8(tupleElement(`choice_name`, 'value'))),
  CONSTRAINT `invariant.attributes.json` CHECK isNull(`attributes`) OR (isValidJSON(assumeNotNull(`attributes`))),
  CONSTRAINT `invariant.opaque.json` CHECK isNull(`opaque`) OR (isValidJSON(assumeNotNull(`opaque`))),
  CONSTRAINT `invariant.json_value.json` CHECK isNull(`json_value`) OR (isValidJSON(assumeNotNull(`json_value`))),
  CONSTRAINT `invariant.json_list.json` CHECK isNull(`json_list`) OR (isValidJSON(assumeNotNull(`json_list`)))
